}
static vector<vector<char>> readChar2D(Tok& tok){
    string arr=tok.nextToken();
    if(arr=="[]"||arr.empty())return {};
    auto rows=splitTop(innerArr(arr)); vector<vector<char>> mat;
    for(auto&r:rows){Tok t2;t2.s="["+innerArr(r)+"]";t2.pos=0;mat.push_back(readCharVec(t2));} return mat;
}
